            [("Expression.Error: column not found", "Expression.Error：找不到列"), ("Source column renamed or removed; a step refers to the old name", "源列被改名或删除；某步骤仍引用旧名称"), ("Edit the step (often Changed Type) or rename back", "编辑该步骤（通常是「更改的类型」）或改回原名")],
            [("DataSource.Error: could not find file", "DataSource.Error：找不到文件"), ("File moved or renamed", "文件被移动或改名"), ("Data source settings → Change Source", "数据源设置 → 更改源")],
            [("Credentials error", "凭据错误"), ("Password changed or OAuth token expired", "密码更改或 OAuth 令牌过期"), ("Edit credentials in Desktop or the semantic model settings", "在 Desktop 或语义模型设置中编辑凭据")],
            [("Formula.Firewall", "Formula.Firewall"), ("Sources with incompatible privacy levels combined", "合并了隐私级别不兼容的来源"), ("Set correct privacy levels, or restructure queries", "设定正确的隐私级别，或调整查询结构")],
