            [("Merge columns", "合并列"), ("Join text columns with a separator, e.g. a composite key", "用分隔符把文字列合并，例如组合键")],
            [("Extract", "提取"), ("Length, first/last characters, text between delimiters", "长度、前/后几个字符、分隔符之间的文字")],
